WITH all_ebudget_data AS (
    -- 1. VET Manpower
    SELECT 'VET Manpower' AS ประเภท, v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id AS รหัสสาขา, v.base_sub_branch_id, v.department_id, mc.cost_center_code, v.cost_center_name, mc.description AS cost_center_description, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.general_ledger_code, glm.gl_name, glm.proportion AS gl_proportion, glm.depreciation AS gl_depreciation, NULL::character varying AS position_allowance_gl_code, NULL::character varying AS position_allowance_gl_name, NULL::character varying AS budget_category, NULL::character varying AS item_code, v.item_master_id, v.position_name AS รายละเอียด, v.description, NULL::character varying AS adjustment_type, NULL::character varying AS old_position_name, NULL::character varying AS old_description, NULL::character varying AS new_position_name, NULL::character varying AS new_description, NULL::numeric(12, 2) AS old_salary, NULL::numeric(12, 2) AS old_allowance, NULL::numeric(12, 2) AS new_salary, NULL::numeric(12, 2) AS new_allowance, NULL::numeric(12, 2) AS diff_salary, NULL::numeric(12, 2) AS diff_allowance, COALESCE(v.salary, im.salary) AS salary, im.estimated_shift_allowance, im.position_allowance, im.total_salary, im.purchase_price, md.month, md.headcount, md.cost, NULL::numeric(14, 2) AS amount, NULL::numeric(14, 2) AS cumulative_amount, NULL::character varying AS monthly_detail_note, NULL::bigint AS template_row_id, NULL::integer AS row_order, NULL::character varying AS row_type, NULL::numeric(14, 2) AS actual_value, NULL::numeric(14, 2) AS per_month_value, NULL::numeric(14, 2) AS annualized_value, NULL::numeric(14, 2) AS sales_ratio, NULL::numeric(14, 2) AS growth_rate, NULL::integer AS actual_month_count, NULL::numeric(5, 2) AS growth_pct_1, NULL::numeric(5, 2) AS growth_pct_2, NULL::numeric(5, 2) AS growth_pct_3, md.vet_budget_id::bigint AS source_line_id
    FROM intra_tl.ebudget_vet_manpower v LEFT JOIN intra_tl.ebudget_monthly_detail md ON md.vet_budget_id = v.id LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_budget_item_master im ON im.id = v.item_master_id LEFT JOIN intra_tl.master_data_ebudget_cost_center_master mc ON v.cost_center_name = mc.cost_center_name
    UNION ALL
    -- 2.1 NON VET (Salary)
    SELECT 'NON VET Manpower', v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id, v.base_sub_branch_id, v.department_id, mc.cost_center_code, v.cost_center_name, mc.description, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.salary_general_ledger_code, glm.gl_name, glm.proportion, glm.depreciation, v.position_allowance_general_ledger_code, glm_allow.gl_name, NULL::character varying, NULL::character varying, v.item_master_id, v.position_name, v.description, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), COALESCE(v.salary, im.salary), im.estimated_shift_allowance, COALESCE(v.position_allowance, im.position_allowance), im.total_salary, im.purchase_price, md.month, md.headcount, md.cost, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::character varying, NULL::bigint, NULL::integer, 'Salary_Line'::character varying, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::integer, NULL::numeric(5, 2), NULL::numeric(5, 2), NULL::numeric(5, 2), md.non_vet_budget_id::bigint
    FROM intra_tl.ebudget_non_vet_manpower v LEFT JOIN intra_tl.ebudget_monthly_detail md ON md.non_vet_budget_id = v.id LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.salary_general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm_allow ON glm_allow.gl_code = v.position_allowance_general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_budget_item_master im ON im.id = v.item_master_id LEFT JOIN intra_tl.master_data_ebudget_cost_center_master mc ON v.cost_center_name = mc.cost_center_name
    UNION ALL
    -- 2.2 NON VET (Allowance)
    SELECT 'NON VET Manpower', v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id, v.base_sub_branch_id, v.department_id, mc.cost_center_code, v.cost_center_name, mc.description, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.position_allowance_general_ledger_code, glm_allow.gl_name, glm.proportion, glm.depreciation, v.position_allowance_general_ledger_code, glm_allow.gl_name, NULL::character varying, NULL::character varying, v.item_master_id, v.position_name, v.description, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), COALESCE(v.salary, im.salary), im.estimated_shift_allowance, COALESCE(v.position_allowance, im.position_allowance), im.total_salary, im.purchase_price, md.month, md.headcount, md.cost, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::character varying, NULL::bigint, NULL::integer, 'Allowance_Line'::character varying, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::integer, NULL::numeric(5, 2), NULL::numeric(5, 2), NULL::numeric(5, 2), md.non_vet_budget_id::bigint
    FROM intra_tl.ebudget_non_vet_manpower v LEFT JOIN intra_tl.ebudget_monthly_detail md ON md.non_vet_budget_id = v.id LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.salary_general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm_allow ON glm_allow.gl_code = v.position_allowance_general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_budget_item_master im ON im.id = v.item_master_id LEFT JOIN intra_tl.master_data_ebudget_cost_center_master mc ON v.cost_center_name = mc.cost_center_name
