    -- 11. GL Entry
    SELECT 'GL Entry', v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id, NULL::character varying, v.department_id, mc.cost_center_code, v.cost_center_name, mc.description, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.general_ledger_code, glm.gl_name, COALESCE(v.proportion, glm.proportion), COALESCE(v.depreciation, glm.depreciation), NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::bigint, v.detail_note, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), gl.month, NULL::numeric(10, 2), NULL::numeric(14, 2), gl.amount, gl.cumulative_amount, gl.detail_note, NULL::bigint, NULL::integer, NULL::character varying, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::integer, NULL::numeric(5, 2), NULL::numeric(5, 2), NULL::numeric(5, 2), gl.gl_entry_id::bigint
    FROM intra_tl.ebudget_gl_entry v LEFT JOIN intra_tl.ebudget_gl_entry_monthly_detail gl ON gl.gl_entry_id = v.id LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_cost_center_master mc ON v.cost_center_name = mc.cost_center_name
    UNION ALL
    -- 12. Revenue
    SELECT 'Revenue', v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id, NULL::character varying, v.department_id, mc.cost_center_code, v.cost_center_name, mc.description, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.general_ledger_code, glm.gl_name, COALESCE(v.proportion, glm.proportion), COALESCE(v.depreciation, glm.depreciation), NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::bigint, v.detail_note, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), rv.month, NULL::numeric(10, 2), NULL::numeric(14, 2), rv.amount, rv.cumulative_amount, rv.detail_note, NULL::bigint, NULL::integer, NULL::character varying, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::integer, NULL::numeric(5, 2), NULL::numeric(5, 2), NULL::numeric(5, 2), rv.revenue_entry_id::bigint
    FROM intra_tl.ebudget_revenue v LEFT JOIN intra_tl.ebudget_revenue_monthly_detail rv ON rv.revenue_entry_id = v.id LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_cost_center_master mc ON v.cost_center_name = mc.cost_center_name
    UNION ALL
    -- 13. Budget Plan
    SELECT 'Budget Plan', v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id, NULL::character varying, v.department_id, mc.cost_center_code, v.cost_center_name, mc.description, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.general_ledger_code, glm.gl_name, glm.proportion, glm.depreciation, NULL::character varying, NULL::character varying, v.budget_category, v.item_code, NULL::bigint, v.description, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), bp.month, NULL::numeric(10, 2), NULL::numeric(14, 2), bp.amount, NULL::numeric(14, 2), NULL::character varying, NULL::bigint, NULL::integer, NULL::character varying, NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::numeric(14, 2), NULL::integer, NULL::numeric(5, 2), NULL::numeric(5, 2), NULL::numeric(5, 2), bp.plan_item_id::bigint
    FROM intra_tl.ebudget_budget_plan_item v LEFT JOIN intra_tl.ebudget_budget_plan_monthly_detail bp ON bp.plan_item_id = v.id LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.general_ledger_code LEFT JOIN intra_tl.master_data_ebudget_cost_center_master mc ON v.cost_center_name = mc.cost_center_name
    UNION ALL
    -- 14. GL Actual Template
    SELECT 'GL Actual Template', v.document_no, v.budget_year, v.status, v.cancel_reason, v.base_branch_id, NULL::character varying, v.department_id, NULL::character varying, NULL::character varying, NULL::character varying, v.create_eid, v.create_date, v.modify_eid, v.modify_date, v.code, v.label, glm.proportion, glm.depreciation, NULL::character varying, NULL::character varying, NULL::character varying, v.code, NULL::bigint, v.label, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::character varying, NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::numeric(12, 2), NULL::smallint, NULL::numeric(10, 2), v.annualized_value, v.annualized_value, NULL::numeric(14, 2), NULL::character varying, v.template_row_id, v.row_order, v.row_type, v.actual_value, v.per_month_value, v.annualized_value, v.sales_ratio, v.growth_rate, v.actual_month_count, v.growth_pct_1, v.growth_pct_2, v.growth_pct_3, v.template_row_id::bigint
    FROM intra_tl.ebudget_gl_actual_template v LEFT JOIN intra_tl.master_data_ebudget_general_ledger_master glm ON glm.gl_code = v.code
),
budget_calculated AS (
    SELECT *,
        CASE 
            WHEN ประเภท = 'VET Manpower' THEN COALESCE(cost, 0)
            WHEN ประเภท IN ('Revenue', 'GL Entry') THEN COALESCE(amount, 0)
            WHEN ประเภท = 'NON VET Manpower' AND row_type = 'Salary_Line' THEN CASE WHEN COALESCE(cost, 0) = 0 THEN 0 ELSE COALESCE(salary, 0) * (COALESCE(cost, 0)::numeric / NULLIF((COALESCE(salary, 0) + COALESCE(position_allowance, 0)), 0)) END
            WHEN ประเภท = 'NON VET Manpower' AND row_type = 'Allowance_Line' THEN CASE WHEN COALESCE(cost, 0) = 0 THEN 0 ELSE COALESCE(position_allowance, 0) * (COALESCE(cost, 0)::numeric / NULLIF((COALESCE(salary, 0) + COALESCE(position_allowance, 0)), 0)) END
            WHEN ประเภท = 'Position Adjustment' AND row_type = 'Salary_Line' THEN CASE WHEN COALESCE(cost, 0) = 0 THEN 0 ELSE COALESCE(diff_salary, 0) * (COALESCE(cost, 0)::numeric / NULLIF((COALESCE(diff_salary, 0) + COALESCE(diff_allowance, 0)), 0)) END
            WHEN ประเภท = 'Position Adjustment' AND row_type = 'Allowance_Line' THEN CASE WHEN COALESCE(cost, 0) = 0 THEN 0 ELSE COALESCE(diff_allowance, 0) * (COALESCE(cost, 0)::numeric / NULLIF((COALESCE(diff_salary, 0) + COALESCE(diff_allowance, 0)), 0)) END
            WHEN gl_depreciation > 0 THEN ROUND(SUM(COALESCE(cost, 0)::numeric / (NULLIF(gl_depreciation, 0) * 12.0)) OVER (PARTITION BY document_no, รายละเอียด, description, purchase_price ORDER BY month ASC), 2)
            ELSE COALESCE(cost, amount, 0)
        END AS final_amount
    FROM all_ebudget_data
),
pivoted_data AS (
    SELECT general_ledger_code, MAX(gl_name) AS gl_name,
        MAX(CASE WHEN ประเภท = 'GL Actual Template' THEN actual_value ELSE 0 END) AS act_real,
        MAX(CASE WHEN ประเภท = 'GL Actual Template' THEN per_month_value ELSE 0 END) AS per_month,
        MAX(CASE WHEN ประเภท = 'GL Actual Template' THEN annualized_value ELSE 0 END) AS annualized_12,
        MAX(CASE WHEN ประเภท = 'GL Actual Template' THEN sales_ratio ELSE 0 END) AS sales_ratio,
        MAX(CASE WHEN ประเภท = 'GL Actual Template' THEN growth_rate ELSE 0 END) AS growth_rate,
        SUM(CASE WHEN month = 1 THEN final_amount ELSE 0 END) AS january, SUM(CASE WHEN month = 2 THEN final_amount ELSE 0 END) AS february,
        SUM(CASE WHEN month = 3 THEN final_amount ELSE 0 END) AS march, SUM(CASE WHEN month = 4 THEN final_amount ELSE 0 END) AS april,
        SUM(CASE WHEN month = 5 THEN final_amount ELSE 0 END) AS may, SUM(CASE WHEN month = 6 THEN final_amount ELSE 0 END) AS june,
        SUM(CASE WHEN month = 7 THEN final_amount ELSE 0 END) AS july, SUM(CASE WHEN month = 8 THEN final_amount ELSE 0 END) AS august,
        SUM(CASE WHEN month = 9 THEN final_amount ELSE 0 END) AS september, SUM(CASE WHEN month = 10 THEN final_amount ELSE 0 END) AS october,
        SUM(CASE WHEN month = 11 THEN final_amount ELSE 0 END) AS november, SUM(CASE WHEN month = 12 THEN final_amount ELSE 0 END) AS december,
        SUM(CASE WHEN month BETWEEN 1 AND 12 THEN final_amount ELSE 0 END) AS total
    FROM budget_calculated WHERE general_ledger_code IS NOT NULL GROUP BY general_ledger_code
),
template_mapped AS (
    SELECT tr.row_order, tr.code AS template_code, COALESCE(pd.general_ledger_code, tr.code) AS general_ledger_code, COALESCE(pd.gl_name, '') AS gl_name,
        COALESCE(pd.act_real, 0) AS act_real, 
        COALESCE(pd.per_month, 0) AS per_month, 
        COALESCE(pd.annualized_12, 0) AS annualized_12,
        COALESCE(pd.sales_ratio, 0) AS sales_ratio, 
        COALESCE(pd.growth_rate, 0) AS growth_rate,
        COALESCE(pd.january, 0) AS january, COALESCE(pd.february, 0) AS february, COALESCE(pd.march, 0) AS march, COALESCE(pd.april, 0) AS april,
        COALESCE(pd.may, 0) AS may, COALESCE(pd.june, 0) AS june, COALESCE(pd.july, 0) AS july, COALESCE(pd.august, 0) AS august,
        COALESCE(pd.september, 0) AS september, COALESCE(pd.october, 0) AS october, COALESCE(pd.november, 0) AS november, COALESCE(pd.december, 0) AS december, COALESCE(pd.total, 0) AS total
    FROM intra_tl.master_data_ebudget_gl_actual_template_row tr LEFT JOIN pivoted_data pd ON tr.code = pd.general_ledger_code
),
grouped_template AS (
    SELECT *, MIN(CASE WHEN template_code LIKE 'F%' THEN row_order END) OVER (ORDER BY row_order ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING) AS footer_row_order
    FROM template_mapped
),
calculated_totals AS (
    SELECT *,
        SUM(act_real) OVER (PARTITION BY footer_row_order) AS block_act, SUM(per_month) OVER (PARTITION BY footer_row_order) AS block_per_month, SUM(annualized_12) OVER (PARTITION BY footer_row_order) AS block_12,
        SUM(january) OVER (PARTITION BY footer_row_order) AS block_jan, SUM(february) OVER (PARTITION BY footer_row_order) AS block_feb, SUM(march) OVER (PARTITION BY footer_row_order) AS block_mar,
        SUM(april) OVER (PARTITION BY footer_row_order) AS block_apr, SUM(may) OVER (PARTITION BY footer_row_order) AS block_may, SUM(june) OVER (PARTITION BY footer_row_order) AS block_jun,
        SUM(july) OVER (PARTITION BY footer_row_order) AS block_jul, SUM(august) OVER (PARTITION BY footer_row_order) AS block_aug, SUM(september) OVER (PARTITION BY footer_row_order) AS block_sep,
        SUM(october) OVER (PARTITION BY footer_row_order) AS block_oct, SUM(november) OVER (PARTITION BY footer_row_order) AS block_nov, SUM(december) OVER (PARTITION BY footer_row_order) AS block_dec, SUM(total) OVER (PARTITION BY footer_row_order) AS block_total
    FROM grouped_template
)
SELECT 
    row_order, general_ledger_code, gl_name,
    CASE WHEN template_code LIKE 'F%' THEN block_act ELSE act_real END AS "Act จริง",
    CASE WHEN template_code LIKE 'F%' THEN block_per_month ELSE per_month END AS "ต่อเดือน",
    CASE WHEN template_code LIKE 'F%' THEN block_12 ELSE annualized_12 END AS "12",
    CASE WHEN template_code LIKE 'F%' THEN 100 ELSE sales_ratio END AS "สัดส่วน/ยอดขาย",
    CASE WHEN template_code LIKE 'F%' THEN 0 ELSE growth_rate END AS "% การโต",
    CASE WHEN template_code LIKE 'F%' THEN block_jan ELSE january END AS january,
    CASE WHEN template_code LIKE 'F%' THEN block_feb ELSE february END AS february,
    CASE WHEN template_code LIKE 'F%' THEN block_mar ELSE march END AS march,
    CASE WHEN template_code LIKE 'F%' THEN block_apr ELSE april END AS april,
    CASE WHEN template_code LIKE 'F%' THEN block_may ELSE may END AS may,
    CASE WHEN template_code LIKE 'F%' THEN block_jun ELSE june END AS june,
    CASE WHEN template_code LIKE 'F%' THEN block_jul ELSE july END AS july,
    CASE WHEN template_code LIKE 'F%' THEN block_aug ELSE august END AS august,
    CASE WHEN template_code LIKE 'F%' THEN block_sep ELSE september END AS september,
    CASE WHEN template_code LIKE 'F%' THEN block_oct ELSE october END AS october,
    CASE WHEN template_code LIKE 'F%' THEN block_nov ELSE november END AS november,
    CASE WHEN template_code LIKE 'F%' THEN block_dec ELSE december END AS december,
    CASE WHEN template_code LIKE 'F%' THEN block_total ELSE total END AS total,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_jan = 0 THEN 0 ELSE 100 END ELSE (january::numeric / NULLIF(block_jan, 0)) * 100.0 END AS pct_jan,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_feb = 0 THEN 0 ELSE 100 END ELSE (february::numeric / NULLIF(block_feb, 0)) * 100.0 END AS pct_feb,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_mar = 0 THEN 0 ELSE 100 END ELSE (march::numeric / NULLIF(block_mar, 0)) * 100.0 END AS pct_mar,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_apr = 0 THEN 0 ELSE 100 END ELSE (april::numeric / NULLIF(block_apr, 0)) * 100.0 END AS pct_apr,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_may = 0 THEN 0 ELSE 100 END ELSE (may::numeric / NULLIF(block_may, 0)) * 100.0 END AS pct_may,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_jun = 0 THEN 0 ELSE 100 END ELSE (june::numeric / NULLIF(block_jun, 0)) * 100.0 END AS pct_jun,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_jul = 0 THEN 0 ELSE 100 END ELSE (july::numeric / NULLIF(block_jul, 0)) * 100.0 END AS pct_jul,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_aug = 0 THEN 0 ELSE 100 END ELSE (august::numeric / NULLIF(block_aug, 0)) * 100.0 END AS pct_aug,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_sep = 0 THEN 0 ELSE 100 END ELSE (september::numeric / NULLIF(block_sep, 0)) * 100.0 END AS pct_sep,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_oct = 0 THEN 0 ELSE 100 END ELSE (october::numeric / NULLIF(block_oct, 0)) * 100.0 END AS pct_oct,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_nov = 0 THEN 0 ELSE 100 END ELSE (november::numeric / NULLIF(block_nov, 0)) * 100.0 END AS pct_nov,
    CASE WHEN template_code LIKE 'H%' THEN 0 WHEN template_code LIKE 'F%' THEN CASE WHEN block_dec = 0 THEN 0 ELSE 100 END ELSE (december::numeric / NULLIF(block_dec, 0)) * 100.0 END AS pct_dec
FROM calculated_totals
ORDER BY row_order ASC;